mapper.select:
SELECT * FROM games.garden_listing
WHERE family_id = #{familyId} AND status = 'ACTIVE' AND expires_at < #{now}
LIMIT 100

mapper.update:
UPDATE games.garden_listing SET status = 'SOLD'
WHERE id = #{id} AND family_id = #{familyId} AND status = 'ACTIVE'
  AND expires_at > #{now} AND seller_uid != #{buyerUid}
